import csv
import json
import sys


def main():
    path = sys.argv[1]
    merges = {}
    with open(path, encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            print(json.dumps([]))
            return
        header_lower = [h.strip().casefold() for h in header]
        try:
            item_idx = header_lower.index('item')
            qty_idx = header_lower.index('quantity')
        except ValueError:
            print(json.dumps([]))
            return
        for row in reader:
            if len(row) <= max(item_idx, qty_idx):
                continue
            raw_item = row[item_idx]
            raw_qty = row[qty_idx]
            name = ' '.join(raw_item.split()).casefold()
            if not name:
                continue
            qty_str = raw_qty.strip()
            if qty_str == '':
                qty = 1
            else:
                qty = int(qty_str)
            if name in merges:
                merges[name] += qty
            else:
                merges[name] = qty

    result = [{"item": k, "quantity": merges[k]} for k in sorted(merges.keys())]
    print(json.dumps(result))


if __name__ == '__main__':
    main()
